use core::cell::Cell;
use solana_program::program_error::ProgramError;
struct NIO_Cell { counter:Cell<i64>, payload:Cell<u8> }
struct NIO_Guard<'a> { cell:&'a NIO_Cell }
impl Drop for NIO_Guard<'_> {
 fn drop(&mut self) {assert!(self.cell.counter.get()==-1);self.cell.counter.set(0);}
}
fn NIO_acquire(c:&NIO_Cell)->Result<NIO_Guard<'_>,ProgramError>{
 if c.counter.get()==0 {c.counter.set(-1);Ok(NIO_Guard{cell:c})}
 else {Err(ProgramError::AccountBorrowFailed)}
}
struct NIO_Log { next:u8, fail:u8, code:u64 }
fn NIO_payload(g:&NIO_Guard<'_>,l:&mut NIO_Log)->Result<(),ProgramError>{
 assert!(g.cell.counter.get()==-1);g.cell.payload.set(kani::any());
 let tag=l.next;l.next+=1;
 if l.fail==tag {Err(ProgramError::from(l.code))} else {Ok(())}
}
fn NIO_framed_child(c:&NIO_Cell,l:&mut NIO_Log)->Result<(),ProgramError>{
 let n=c.counter.get();assert!(n>=0 && n<i64::MAX);
 c.counter.set(n+1);c.payload.set(kani::any());c.counter.set(c.counter.get()-1);
 let tag=l.next;l.next+=1;
 if l.fail==tag {Err(ProgramError::from(l.code))} else {Ok(())}
}

fn NIO_reference(a:[&NIO_Cell;4],l:&mut NIO_Log)->Result<(),ProgramError>{
{let temporary=NIO_acquire(a[0])?;NIO_payload(&temporary,l)?;}
{let temporary=NIO_acquire(a[1])?;NIO_payload(&temporary,l)?;}
{let temporary=NIO_acquire(a[2])?;NIO_payload(&temporary,l)?;}
Ok(())
}
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NIO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NIO_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NIO_KMX::KMX_realloc)]
#[kani::proof]
fn certificate(){let n0:i64=kani::any();kani::assume(n0>=-1);let c0=NIO_Cell{counter:Cell::new(n0),payload:Cell::new(kani::any())};
let n1:i64=kani::any();kani::assume(n1>=-1);let c1=NIO_Cell{counter:Cell::new(n1),payload:Cell::new(kani::any())};
let n2:i64=kani::any();kani::assume(n2>=-1);let c2=NIO_Cell{counter:Cell::new(n2),payload:Cell::new(kani::any())};
let n3:i64=kani::any();kani::assume(n3>=-1);let c3=NIO_Cell{counter:Cell::new(n3),payload:Cell::new(kani::any())};
kani::assume(n3>=0 && n3<i64::MAX);
let cells=[&c0,&c1,&c2];let m0:usize=kani::any();kani::assume(m0<3);let m1:usize=kani::any();kani::assume(m1<3);let m2:usize=kani::any();kani::assume(m2<3);
let mut log=NIO_Log{next:0,fail:kani::any(),code:kani::any()};let _result=NIO_reference([cells[m0],cells[m1],cells[m2],&c3],&mut log);
if c0.counter.get()==0 {let retained=NIO_acquire(&c0).unwrap();core::mem::forget(retained);}
assert!(c0.counter.get()==n0);
assert!(c1.counter.get()==n1);
assert!(c2.counter.get()==n2);
assert!(c3.counter.get()==n3);
}
